with ins as (insert into public.artist_discography (artist_slug,artist_id,title,release_type,release_date,year,label,source_url) select x.s,a.id,x.ti,x.ty,x.d::date,x.y,x.l,x.u from json_to_recordset('[{"s":"aaguu","ti":"Sampadan 19 (AAGUU remix), on Todh Teri - Deep In India Vol. 6","ty":"remix","y":2019,"d":"2019-11-29","l":"Todh Teri","u":"https://soundcloud.com/todhteri/b1-todh-teri-sampadan-20"},{"s":"okedo","ti":"Soft Serve (Side A)","ty":"album","y":2025,"d":"2025-06-04","l":null,"u":"https://okedo.bandcamp.com/album/soft-serve-side-a"},{"s":"okedo","ti":"Soft Serve (Side B)","ty":"album","y":2025,"d":"2025-06-11","l":null,"u":"https://okedo.bandcamp.com/album/soft-serve-side-b-2"}]'::json) as x(s text,ti text,ty text,y int,d text,l text,u text) join public.artists a on a.slug=x.s where not exists (select 1 from public.artist_discography d where d.artist_slug=x.s and lower(d.title)=lower(x.ti)) on conflict do nothing returning 1) select count(*) from ins;